}

export function RunDetail() {
  const { runId } = useParams<{ runId: string }>()
  const navigate = useNavigate()
  const [activeTab, setActiveTab] = useState<'steps' | 'logs' | 'metrics'>('steps')
  const [logFilter, setLogFilter] = useState<string>('all')

  const { data: run, isLoading } = useQuery({
    queryKey: ['run', runId],
    queryFn: () => runsApi.getById(runId!),
    initialData: mockRun as any,
  })

  const { data: stepsData } = useQuery({
    queryKey: ['run', runId, 'steps'],
    queryFn: () => runsApi.getSteps(runId!),
    initialData: { items: mockSteps } as any,
  })

  const steps = stepsData?.items || []
  const logs = mockLogs

  const filteredLogs = logFilter === 'all' ? logs : logs.filter(l => l.level === logFilter)

  if (isLoading) {
    return (
      <div className="space-y-6">
        <Skeleton className="h-12 w-64" />
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <Skeleton className="h-48" />
          <Skeleton className="h-48 lg:col-span-2" />
        </div>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-start justify-between">
        <div className="flex items-start gap-4">
          <Button variant="ghost" size="sm" onClick={() => navigate(-1)}>
            <ArrowLeft className="w-4 h-4 mr-1" />
            Back
          </Button>
          <div>
            <div className="flex items-center gap-3">
              <h1 className="text-2xl font-bold">Run #{run?.run_number}</h1>
              <Badge className={getStatusBgColor(run?.status || 'pending')}>
                <StatusIcon status={run?.status || 'pending'} />
                <span className="ml-1">{run?.status}</span>
              </Badge>
            </div>
            <p className="text-muted-foreground mt-1 flex items-center gap-2">
              <GitBranch className="w-4 h-4" />
              {run?.pipeline_name}
              <span className="text-border">•</span>
              <Clock className="w-4 h-4" />
              {formatDate(run?.started_at || '')}
              <span className="text-border">•</span>
              {formatDuration(run?.duration_seconds || 0)}
            </p>
          </div>
        </div>
        <div className="flex gap-2">
          {run?.status === 'running' && (
            <Button variant="destructive" size="sm">
              <XCircle className="w-4 h-4 mr-1" />
              Cancel
            </Button>
          )}
        </div>
      </div>

      {/* Metrics Cards */}
      {run?.metrics && (
        <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
          {Object.entries(run.metrics).map(([key, value]) => (
            <Card key={key}>
              <CardContent className="p-4 text-center">
                <p className="text-2xl font-bold text-primary">
                  {typeof value === 'number' ? (value > 1 ? value.toFixed(2) : `${(value * 100).toFixed(1)}%`) : value}
                </p>
                <p className="text-xs text-muted-foreground uppercase mt-1">{key}</p>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {/* Tabs */}
      <div className="border-b">
        <div className="flex gap-1">
          {(['steps', 'logs', 'metrics'] as const).map((tab) => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={cn(
                'px-4 py-2 text-sm font-medium border-b-2 transition-colors capitalize',
                activeTab === tab
                  ? 'border-primary text-primary'
                  : 'border-transparent text-muted-foreground hover:text-foreground'
              )}
            >
              {tab}
            </button>
          ))}
        </div>
      </div>

      {/* Steps Tab */}
      {activeTab === 'steps' && (
        <Card>
          <CardContent className="p-0">
            <div className="divide-y">
              {steps.map((step, index) => (
                <div key={step.id} className="p-4 hover:bg-muted/30 transition-colors">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <div className="flex items-center justify-center w-8 h-8 rounded-full bg-muted text-xs font-mono text-muted-foreground">
                        {index + 1}
                      </div>
                      <div>
                        <p className="font-medium text-sm">{step.name}</p>
                        <p className="text-xs text-muted-foreground">{step.step_type}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-4">
                      <Badge className={getStatusBgColor(step.status)}>
                        <StatusIcon status={step.status} />
                        <span className="ml-1">{step.status}</span>
                      </Badge>
                      {step.duration_seconds !== undefined && (
                        <span className="text-xs text-muted-foreground font-mono">
                          {formatDuration(step.duration_seconds)}
                        </span>
                      )}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}

      {/* Logs Tab */}
      {activeTab === 'logs' && (
        <Card className="overflow-hidden">
          <CardHeader className="py-3 px-4 border-b bg-muted/30">
            <div className="flex items-center justify-between">
              <CardTitle className="text-sm">Log Output</CardTitle>
              <div className="flex gap-1">
                {['all', 'INFO', 'DEBUG', 'WARNING', 'ERROR'].map((level) => (
                  <button
                    key={level}
                    onClick={() => setLogFilter(level)}
                    className={cn(
                      'px-2 py-1 text-xs rounded transition-colors',
                      logFilter === level ? 'bg-primary text-primary-foreground' : 'hover:bg-muted'
                    )}
                  >
                    {level}
                  </button>
                ))}
              </div>
            </div>
          </CardHeader>
          <CardContent className="p-0">
            <div className="bg-[#0d1117] text-gray-300 font-mono text-xs overflow-auto max-h-[500px]">
              {filteredLogs.map((log, i) => (
                <div key={i} className="flex gap-3 px-4 py-1 hover:bg-white/5">
                  <span className="text-gray-600 whitespace-nowrap shrink-0">
                    {new Date(log.timestamp).toLocaleTimeString()}
                  </span>
                  <span className={cn('font-semibold shrink-0 w-10', LEVEL_COLORS[log.level])}>
                    {log.level}
                  </span>
                  <span className="text-gray-400 shrink-0">[{log.step}]</span>
                  <span className="text-gray-200 break-all">{log.message}</span>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}

      {/* Metrics Tab */}
      {activeTab === 'metrics' && (
        <Card>
          <CardContent className="p-6">
            <p className="text-muted-foreground text-sm">
              Metric visualization coming soon. Current metrics are displayed in the cards above.
            </p>
          </CardContent>
        </Card>
      )}
    </div>
  )
}
